learn.code:
p { color: black; }
.note { color: gray; }
#title { font-size: 2em; }
/* html: <p class="note"> */

h1, h2 { color: navy; }
nav a { text-decoration: none; }
ul > li { margin: 4px; }
a:hover { color: red; }

h1 {
  color: #1e90ff;
  background-color: rgb(240, 240, 240);
}
p { color: rgba(0, 0, 0, 0.7); }

body {
  font-family: "Segoe UI", Arial, sans-serif;
  font-size: 16px;
}
h1 { font-size: 2rem; }

p {
  font-weight: bold;
  font-style: italic;
  text-align: center;
  line-height: 1.5;
}

.box {
  width: 200px;
  padding: 10px;
  border: 2px solid black;
  margin: 20px;
}

* {
  box-sizing: border-box;
}
.card {
  width: 300px;
  border: 1px solid #ccc;
  border-radius: 8px;
}

.wrap {
  width: 600px;
  margin: 0 auto;
}
span { display: inline-block; }

.col {
  display: flex;
  flex-direction: column;
  flex-wrap: wrap;
}

.center {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 12px;
  height: 200px;
}

.page {
  display: grid;
  grid-template-areas:
    "head head"
    "nav main";
}
.head { grid-area: head; }
.cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
}

img {
  max-width: 100%;
  height: auto;
}
.container {
  width: 90%;
  max-width: 900px;
}

.cards { display: grid; grid-template-columns: 1fr; }
@media (min-width: 700px) {
  .cards { grid-template-columns: repeat(3, 1fr); }
}
@media (prefers-color-scheme: dark) {
  body { background: #111; color: #eee; }
}
